def transform(grid):
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(r.count(x) for r in grid))
    color = next(x for x in set(x for row in grid for x in row) if x != bg)
    for row in out:
        for c in range(1, len(row) - 1):
            if row[c] == bg and row[c - 1] == color and row[c + 1] == color:
                row[c] = 2
    return out
